"""Concatenate src/*.js into bootstrap.js (Zotero loads a single bootstrap file).

Edit the modules in src/, then run `python scripts/bundle.py`. `--check` fails if bootstrap.js is stale.
"""

import argparse
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
HEADER = (
    "// SPDX-License-Identifier: AGPL-3.0-only\n"
    "// GENERATED by scripts/bundle.py from src/*.js. Edit the modules in src/, not this file.\n"
)


def bundle():
    parts = [HEADER]
    for module in sorted((ROOT / "src").glob("*.js")):
        body = "".join(line for line in module.read_text(encoding="utf-8").splitlines(keepends=True)
                       if not line.startswith("// SPDX-License-Identifier"))
        parts.append(f"\n// ---- src/{module.name} ----\n{body.rstrip()}\n")
    return "".join(parts)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="exit 1 if bootstrap.js is out of date")
    args = parser.parse_args()
    target = ROOT / "bootstrap.js"
    result = bundle()
    if args.check:
        if target.read_text(encoding="utf-8") != result:
            sys.exit("bootstrap.js is out of date: run python scripts/bundle.py")
        return
    target.write_text(result, encoding="utf-8")
    print(target)


if __name__ == "__main__":
    main()
